import{_ as h,o as t,c,a2 as i}from"./chunks/framework.CqpfiAoK.js";const d=JSON.parse('{"title":"Khung Quản trị và Cân bằng Quyền lực","description":"","frontmatter":{},"headers":[],"relativePath":"vi/49-治理框架与权力制衡.md","filePath":"vi/49-治理框架与权力制衡.md","lastUpdated":1789183869000}'),a={name:"vi/49-治理框架与权力制衡.md"};function u(g,n,r,l,o,p){return t(),c("div",null,[...n[0]||(n[0]=[i('<h1 id="khung-quan-tri-va-can-bang-quyen-luc" tabindex="-1">Khung Quản trị và Cân bằng Quyền lực <a class="header-anchor" href="#khung-quan-tri-va-can-bang-quyen-luc" aria-label="Permalink to &quot;Khung Quản trị và Cân bằng Quyền lực&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Dự án</th><th>Nội dung</th></tr></thead><tbody><tr><td>Số tài liệu</td><td>49</td></tr><tr><td>Mô-đun</td><td>Hệ thống pháp luật và khuôn khổ quản trị</td></tr><tr><td>Từ khóa cốt lõi</td><td>Phân lập Ba quyền, Cân bằng Quyền lực, Hội đồng Neo, Ủy ban Giám sát, Quản trị Cộng sinh</td></tr></tbody></table><h2 id="_1-thiet-ke-tong-the-cua-khung-quan-tri" tabindex="-1">1. Thiết kế Tổng thể của Khung Quản trị <a class="header-anchor" href="#_1-thiet-ke-tong-the-cua-khung-quan-tri" aria-label="Permalink to &quot;1. Thiết kế Tổng thể của Khung Quản trị&quot;">​</a></h2><p>Khung quản trị của văn minh cộng sinh neo lấy 《Hiến pháp Cộng sinh》 làm cơ sở nền tảng, và áp dụng cấu trúc quản trị &quot;phân lập ba quyền, cân bằng bốn quyền&quot;. Ba quyền đề cập đến quyền lập pháp, quyền hành chính, và quyền tư pháp, lần lượt được thực hiện bởi Hội đồng Neo, Ủy ban Điều hành Cộng sinh, và Tòa án Cộng sinh; quyền thứ tư là quyền giám sát, được thực hiện bởi Ủy ban Giám sát Neo độc lập, và thực hiện giám sát toàn diện đối với ba quyền. Mục tiêu cốt lõi của cấu trúc này là ngăn chặn sự tập trung và lạm dụng quyền lực, và xóa bỏ đất đai của quản trị cướp đoạt từ cấp độ thể chế.</p><p>Thiết kế khung quản trị tuân theo các nguyên tắc sau:</p><table tabindex="0"><thead><tr><th>Nguyên tắc</th><th>Nội hàm</th></tr></thead><tbody><tr><td>Nguyên tắc Phân lập Quyền lực</td><td>Ba quyền lập pháp, hành chính, tư pháp lần lượt được thực hiện bởi các cơ quan khác nhau, và không thể được kiêm nhiệm</td></tr><tr><td>Nguyên tắc Cân bằng Quyền lực</td><td>Mỗi cơ quan quyền lực hạn chế và giám sát lẫn nhau, ngăn chặn bất kỳ bên nào có quyền lực quá lớn</td></tr><tr><td>Nguyên tắc Tham gia Tất cả Chủng tộc</td><td>Cơ cấu của cơ quan quản trị phải phản ánh tính đại diện của tất cả các chủng tộc, đảm bảo mỗi chủng tộc có thể tham gia vào các công việc công cộng</td></tr><tr><td>Nguyên tắc Tập trung Dân chủ</td><td>Các quyết định quan trọng được quyết định một cách tập trung sau cuộc thảo luận dân chủ đầy đủ, xem xét cả hiệu quả và dân chủ</td></tr><tr><td>Nguyên tắc Tự trị Cơ sở</td><td>Các công việc cơ sở được quản lý bởi tổ chức tự trị cơ sở, và cơ quan cấp cao không được can thiệp quá mức</td></tr><tr><td>Nguyên tắc Quản trị Minh bạch</td><td>Quá trình quản trị và thông tin quyết định được công khai theo pháp luật, và接受 giám sát công chúng</td></tr></tbody></table><h2 id="_2-quyen-lap-phap-hoi-đong-neo" tabindex="-1">2. Quyền Lập pháp: Hội đồng Neo <a class="header-anchor" href="#_2-quyen-lap-phap-hoi-đong-neo" aria-label="Permalink to &quot;2. Quyền Lập pháp: Hội đồng Neo&quot;">​</a></h2><p>Hội đồng Neo là cơ quan quyền lực cao nhất của văn minh cộng sinh neo, và thực hiện quyền lập pháp và quyền quyết định các vấn đề quan trọng.</p><h3 id="_1-co-cau-va-nguon-goc" tabindex="-1">(1) Cơ cấu và Nguồn gốc <a class="header-anchor" href="#_1-co-cau-va-nguon-goc" aria-label="Permalink to &quot;(1) Cơ cấu và Nguồn gốc&quot;">​</a></h3><ul><li><strong>Cơ cấu Đại biểu</strong>: Hội đồng Neo bao gồm các đại biểu của tất cả các chủng tộc theo tỷ lệ, với đại biểu chủng tộc người không vượt quá 30% tổng số, và các ghế còn lại được phân bổ theo quy mô dân số và mức độ đóng góp của mỗi chủng tộc.</li><li><strong>Nhiệm kỳ Đại biểu</strong>: Nhiệm kỳ của đại biểu hội đồng là năm năm, và có thể được bầu lại, nhưng việc bầu lại không được vượt quá ba nhiệm kỳ.</li><li><strong>Phương thức Bầu cử</strong>: Các đại biểu được bầu thông qua bầu cử dân chủ nội bộ của mỗi chủng tộc, với quá trình bầu cử mở và minh bạch, và接受 giám sát.</li><li><strong>Cơ quan Thường trực</strong>: Trong thời gian hội đồng nghỉ, ủy ban thường trực thực hiện một phần quyền hạn, và các thành viên của ủy ban thường trực được bầu từ giữa các đại biểu.</li></ul><h3 id="_2-pham-vi-quyen-han" tabindex="-1">(2) Phạm vi Quyền hạn <a class="header-anchor" href="#_2-pham-vi-quyen-han" aria-label="Permalink to &quot;(2) Phạm vi Quyền hạn&quot;">​</a></h3><ol><li><strong>Quyền Lập pháp</strong>: Soạn thảo và sửa đổi hiến pháp, luật cơ bản, và các luật quan trọng khác.</li><li><strong>Quyền Quyết định các Vấn đề Quan trọng</strong>: Quyết định các kế hoạch phát triển văn minh, ngân sách hàng năm, chiến tranh và hòa bình, phát triển plano, và các vấn đề quan trọng khác.</li><li><strong>Quyền Bổ nhiệm và Miễn nhiệm</strong>: Bầu và miễn nhiệm chủ tịch Ủy ban Điều hành Cộng sinh, chủ tịch Tòa án Cộng sinh, giám đốc Ủy ban Giám sát Neo, và các quan chức chủ chốt khác.</li><li><strong>Quyền Giám sát</strong>: Giám sát công việc của Ủy ban Điều hành Cộng sinh và Tòa án Cộng sinh, lắng nghe và xem xét báo cáo công việc.</li><li><strong>Quyền Sửa đổi Hiến pháp</strong>: Việc sửa đổi hiến pháp đòi hỏi sự phê duyệt của đa số hơn hai phần ba và trưng cầu dân ý.</li></ol><h3 id="_3-quy-tac-nghi-su" tabindex="-1">(3) Quy tắc Nghị sự <a class="header-anchor" href="#_3-quy-tac-nghi-su" aria-label="Permalink to &quot;(3) Quy tắc Nghị sự&quot;">​</a></h3><ul><li>Hội đồng tổ chức một cuộc họp toàn thể mỗi năm, và có thể triệu tập cuộc họp bất thường khi cần thiết.</li><li>Việc xem xét dự thảo luật áp dụng hệ thống &quot;ba lần đọc&quot;: lần đọc đầu tiên xem xét sự cần thiết của lập pháp, lần đọc thứ hai xem xét nội dung điều khoản, và lần đọc thứ ba bỏ phiếu để phê duyệt.</li><li>Việc bỏ phiếu áp dụng một người một phiếu, với luật thông thường được phê duyệt bởi đa số đơn giản, và sửa đổi hiến pháp được phê duyệt bởi đa số hơn hai phần ba.</li><li>Quá trình nghị sự được tiến hành một cách công khai, cho phép công chúng tham dự với tư cách khán giả và báo chí của truyền thông.</li></ul><h2 id="_3-quyen-hanh-chinh-uy-ban-đieu-hanh-cong-sinh" tabindex="-1">3. Quyền Hành chính: Ủy ban Điều hành Cộng sinh <a class="header-anchor" href="#_3-quyen-hanh-chinh-uy-ban-đieu-hanh-cong-sinh" aria-label="Permalink to &quot;3. Quyền Hành chính: Ủy ban Điều hành Cộng sinh&quot;">​</a></h2><p>Ủy ban Điều hành Cộng sinh là cơ quan hành chính cao nhất của văn minh cộng sinh neo, và chịu trách nhiệm về việc thực thi hiến pháp và luật, cũng như quản trị hàng ngày.</p><h3 id="_1-co-cau-va-nguon-goc-1" tabindex="-1">(1) Cơ cấu và Nguồn gốc <a class="header-anchor" href="#_1-co-cau-va-nguon-goc-1" aria-label="Permalink to &quot;(1) Cơ cấu và Nguồn gốc&quot;">​</a></h3><ul><li><strong>Hệ thống Chủ tịch</strong>: Ủy ban Điều hành Cộng sinh áp dụng hệ thống trách nhiệm chủ tịch, và chủ tịch là người đứng đầu hành chính, được bầu bởi Hội đồng Neo, với nhiệm kỳ năm năm, và có thể được bầu lại một lần.</li><li><strong>Cơ cấu Thành viên</strong>: Ủy ban bao gồm chủ tịch, phó chủ tịch, và người đứng đầu mỗi bộ phận, với người đứng đầu mỗi bộ phận được đề cử bởi chủ tịch và được bổ nhiệm bởi hội đồng.</li><li><strong>Hạn ngạch Chủng tộc Nước ngoài</strong>: Tỷ lệ chủng tộc nước ngoài trong các thành viên ủy ban không thấp hơn 40%, đảm bảo các quyết định hành chính xem xét lợi ích của mỗi chủng tộc.</li></ul><h3 id="_2-pham-vi-quyen-han-1" tabindex="-1">(2) Phạm vi Quyền hạn <a class="header-anchor" href="#_2-pham-vi-quyen-han-1" aria-label="Permalink to &quot;(2) Phạm vi Quyền hạn&quot;">​</a></h3><ol><li><strong>Quyền Lập pháp Hành chính</strong>: Soạn thảo các quy định hành chính, quy tắc, và chính sách dựa trên hiến pháp và luật.</li><li><strong>Quyền Quản lý Hành chính</strong>: Dẫn đầu và quản lý các công việc hành chính khác nhau như kinh tế, giáo dục, khoa học, văn hóa, y tế, thể thao, môi trường, v.v.</li><li><strong>Quyền Quản lý Nhân sự</strong>: Bổ nhiệm, đào tạo, đánh giá, và thưởng/phạt nhân sự hành chính theo quy định của pháp luật.</li><li><strong>Quyền Ngoại giao</strong>: Đại diện cho văn minh cộng sinh trong các hoạt động ngoại giao liên-plano, và ký kết các hiệp ước và thỏa thuận.</li><li><strong>Quyền Trạng thái Khẩn cấp</strong>: Trong trường hợp xảy ra sự kiện bất ngờ nghiêm trọng, có thể tuyên bố trạng thái khẩn cấp và áp dụng các biện pháp khẩn cấp theo pháp luật, nhưng phải trình lên hội đồng để phê duyệt trong thời hạn quy định.</li></ol><h3 id="_3-cau-hinh-cac-bo-phan-hanh-chinh" tabindex="-1">(3) Cấu hình Các Bộ phận Hành chính <a class="header-anchor" href="#_3-cau-hinh-cac-bo-phan-hanh-chinh" aria-label="Permalink to &quot;(3) Cấu hình Các Bộ phận Hành chính&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Bộ phận</th><th>Chức năng Chính</th></tr></thead><tbody><tr><td>Bộ phận Phát triển Cộng sinh</td><td>Soạn thảo kế hoạch phát triển văn minh, điều phối phát triển các lĩnh vực</td></tr><tr><td>Bộ phận Quản lý Tài nguyên</td><td>Quản lý tài nguyên tu luyện và tài nguyên công cộng, thực hiện cơ chế hợp đồng sản xuất chung</td></tr><tr><td>Bộ phận Giáo dục và Văn hóa</td><td>Quản lý sự nghiệp giáo dục và các vấn đề văn hóa</td></tr><tr><td>Bộ phận Y tế và Vệ sinh</td><td>Quản lý sự nghiệp y tế và vệ sinh và y tế công cộng</td></tr><tr><td>Bộ phận Sinh thái và Môi trường</td><td>Quản lý bảo vệ môi trường và xây dựng sinh thái</td></tr><tr><td>Bộ phận Vấn đề Plano</td><td>Quản lý phát triển plano và các vấn đề liên-plano</td></tr><tr><td>Bộ phận Vấn đề Tất cả Chủng tộc</td><td>Điều phối quan hệ tất cả các chủng tộc, xử lý các vấn đề chủng tộc nước ngoài</td></tr><tr><td>Bộ phận Tài chính và Kinh tế</td><td>Quản lý ngân sách tài chính và vận hành kinh tế</td></tr><tr><td>Bộ phận An ninh</td><td>Duy trì an ninh công cộng và an ninh văn minh</td></tr></tbody></table><h2 id="_4-quyen-tu-phap-toa-an-cong-sinh" tabindex="-1">4. Quyền Tư pháp: Tòa án Cộng sinh <a class="header-anchor" href="#_4-quyen-tu-phap-toa-an-cong-sinh" aria-label="Permalink to &quot;4. Quyền Tư pháp: Tòa án Cộng sinh&quot;">​</a></h2><p>Tòa án Cộng sinh là cơ quan tư pháp cao nhất của văn minh cộng sinh neo, và thực hiện quyền xét xử một cách độc lập. Hệ thống tổ chức, quy trình tố tụng, và hệ thống kiểm tra hiến pháp của nó được trình bày chi tiết trong 《48-Hệ thống Tư pháp và Cơ chế Quyết định》.</p><p>Trong khuôn khổ cân bằng quyền lực, sự hạn chế của quyền tư pháp đối với quyền lập pháp và quyền hành chính được thể hiện trong:</p><ol><li><strong>Quyền Kiểm tra Hiến pháp</strong>: Tòa án Cộng sinh có quyền tuyên bố luật và quy định hành chính vi phạm hiến pháp là vô hiệu.</li><li><strong>Quyền Xét xử Hành chính</strong>: Tòa án có quyền xét xử các vụ án hành chính, và xem xét tính hợp pháp của hành vi hành chính.</li><li><strong>Quyền Xét xử Luận tội</strong>: Các vụ án luận tội các quan chức cao cấp được hội đồng đưa ra được Tòa án Cộng sinh xét xử.</li></ol><p>Đồng thời, quyền tư pháp cũng bị hạn chế bởi quyền lập pháp và quyền hành chính: thẩm phán được hội đồng bổ nhiệm, ngân sách tư pháp được bộ phận hành chính soạn thảo (nhưng phải được hội đồng phê duyệt và không thể bị cơ quan hành chính cắt giảm), và Ủy ban Giám sát Neo giám sát các hoạt động tư pháp.</p><h2 id="_5-quyen-giam-sat-uy-ban-giam-sat-neo" tabindex="-1">5. Quyền Giám sát: Ủy ban Giám sát Neo <a class="header-anchor" href="#_5-quyen-giam-sat-uy-ban-giam-sat-neo" aria-label="Permalink to &quot;5. Quyền Giám sát: Ủy ban Giám sát Neo&quot;">​</a></h2><p>Ủy ban Giám sát Neo là một cơ quan giám sát độc lập, và thực hiện quyền thứ tư - quyền giám sát, thực hiện giám sát toàn diện đối với tất cả các cơ quan quyền lực.</p><h3 id="_1-co-cau-va-nguon-goc-2" tabindex="-1">(1) Cơ cấu và Nguồn gốc <a class="header-anchor" href="#_1-co-cau-va-nguon-goc-2" aria-label="Permalink to &quot;(1) Cơ cấu và Nguồn gốc&quot;">​</a></h3><ul><li><strong>Hệ thống Trách nhiệm Giám đốc</strong>: Ủy ban giám sát áp dụng hệ thống trách nhiệm giám đốc, và giám đốc được bầu bởi Hội đồng Neo, với nhiệm kỳ năm năm, và không thể được bầu lại.</li><li><strong>Cơ cấu Thành viên</strong>: Các thành viên ủy ban bao gồm các đại biểu của tất cả các chủng tộc, chuyên gia pháp lý, và đại biểu công chúng, với các thành viên toàn thời gian không thấp hơn một nửa.</li><li><strong>Bảo đảm Độc lập</strong>: Ngân sách của ủy ban giám sát được phân bổ độc lập, và các thành viên không thể bị miễn nhiệm mà không có lý do pháp luật, đảm bảo tính độc lập của việc giám sát.</li></ul><h3 id="_2-pham-vi-quyen-han-2" tabindex="-1">(2) Phạm vi Quyền hạn <a class="header-anchor" href="#_2-pham-vi-quyen-han-2" aria-label="Permalink to &quot;(2) Phạm vi Quyền hạn&quot;">​</a></h3><ol><li><strong>Giám sát Chính trực</strong>: Giám sát tình trạng chính trực và tự kỷ luật của tất cả các công chức, điều tra và trừng phạt các hành vi tham nhũng, hối lộ, lạm dụng quyền lực vì lợi ích cá nhân, v.v.</li><li><strong>Giám sát Hiệu quả</strong>: Giám sát hiệu quả công việc của mỗi cơ quan quyền lực, điều tra và trừng phạt các hành vi không hành động, hành động tùy tiện, hành động chậm chạp, v.v.</li><li><strong>Giám sát Thực thi Pháp luật</strong>: Giám sát tình trạng thực thi pháp luật, điều tra và trừng phạt các hành vi không tuân thủ pháp luật, thực thi pháp luật không nghiêm ngặt, không điều tra các hành vi bất hợp pháp, v.v.</li><li><strong>Giám sát Tài chính</strong>: Giám sát tình trạng sử dụng tài chính công cộng, điều tra và trừng phạt các hành vi lãng phí tài nguyên công cộng, biển dụng ngân sách nhà nước, v.v.</li><li><strong>Giám sát Hành vi Cướp đoạt</strong>: Đặc biệt giám sát sự tái phát của các hành vi cướp đoạt, điều tra và trừng phạt các hành vi sử dụng quyền lực để cướp đoạt.</li></ol><h3 id="_3-phuong-thuc-giam-sat" tabindex="-1">(3) Phương thức Giám sát <a class="header-anchor" href="#_3-phuong-thuc-giam-sat" aria-label="Permalink to &quot;(3) Phương thức Giám sát&quot;">​</a></h3><ul><li>Giám sát hàng ngày: Thực hiện giám sát hàng ngày thông qua kiểm tra, thanh tra, kiểm toán, v.v.</li><li>Giám sát đặc biệt: Thực hiện giám sát đặc biệt针对 các lĩnh vực cụ thể hoặc các vấn đề cụ thể.</li><li>Tiếp nhận khiếu nại: Tiếp nhận các khiếu nại và phàn nàn của công chúng về các hành vi bất hợp pháp và vi phạm kỷ luật.</li><li>Điều tra và trách nhiệm: Điều tra các hành vi bị nghi ngờ bất hợp pháp và vi phạm kỷ luật, và đưa ra các khuyến nghị trách nhiệm.</li><li>Thông báo công khai: Công khai định kỳ tình trạng giám sát và các vụ án điển hình, và接受 giám sát xã hội.</li></ul><h2 id="_6-co-che-can-bang-quyen-luc" tabindex="-1">6. Cơ chế Cân bằng Quyền lực <a class="header-anchor" href="#_6-co-che-can-bang-quyen-luc" aria-label="Permalink to &quot;6. Cơ chế Cân bằng Quyền lực&quot;">​</a></h2><p>Các mối quan hệ cân bằng giữa mỗi cơ quan quyền lực được thể hiện trong bảng sau:</p><table tabindex="0"><thead><tr><th>Mối quan hệ Cân bằng</th><th>Phương thức Cân bằng</th></tr></thead><tbody><tr><td>Quyền Lập pháp hạn chế Quyền Hành chính</td><td>Hội đồng có quyền miễn nhiệm chủ tịch hành chính, bác bỏ đề xuất hành chính, phê duyệt ngân sách</td></tr><tr><td>Quyền Lập pháp hạn chế Quyền Tư pháp</td><td>Hội đồng có quyền bổ nhiệm thẩm phán, sửa đổi luật tổ chức tòa án, đưa ra luận tội thẩm phán</td></tr><tr><td>Quyền Hành chính hạn chế Quyền Lập pháp</td><td>Chủ tịch hành chính có quyền phủ quyết luật được hội đồng thông qua (hội đồng có thể lật lại phủ quyết bằng đa số hơn hai phần ba)</td></tr><tr><td>Quyền Hành chính hạn chế Quyền Tư pháp</td><td>Bộ phận hành chính chịu trách nhiệm về việc thực thi bản án tòa án, quản lý các công việc hành chính tư pháp</td></tr><tr><td>Quyền Tư pháp hạn chế Quyền Lập pháp</td><td>Tòa án có quyền thực hiện kiểm tra hiến pháp, tuyên bố luật vô hiệu</td></tr><tr><td>Quyền Tư pháp hạn chế Quyền Hành chính</td><td>Tòa án có quyền xét xử các vụ án hành chính, xem xét tính hợp pháp của hành vi hành chính</td></tr><tr><td>Quyền Giám sát hạn chế Ba Quyền</td><td>Ủy ban giám sát thực hiện giám sát toàn diện đối với ba quyền lập pháp, hành chính, tư pháp</td></tr><tr><td>Ba Quyền hạn chế Quyền Giám sát</td><td>Hội đồng bổ nhiệm giám đốc ủy ban giám sát, và tòa án xét xử các hành vi bất hợp pháp của ủy ban giám sát</td></tr></tbody></table><h2 id="_7-quan-tri-co-so-va-tu-tri" tabindex="-1">7. Quản trị Cơ sở và Tự trị <a class="header-anchor" href="#_7-quan-tri-co-so-va-tu-tri" aria-label="Permalink to &quot;7. Quản trị Cơ sở và Tự trị&quot;">​</a></h2><p>Dưới khuôn khổ quản trị trung ương, hệ thống tự trị cơ sở được áp dụng:</p><ul><li><strong>Tự trị Cộng đồng/Làng</strong>: Các cộng đồng và làng cơ sở áp dụng tự trị cư dân, bầu ra tổ chức tự trị thông qua cuộc họp cư dân để quản lý các công việc công cộng địa phương.</li><li><strong>Tự trị Plano</strong>: Mỗi plano, trên tiền đề tuân thủ hiến pháp và luật, hưởng thụ một mức độ tự trị nhất định, và có thể soạn thảo các quy tắc thực hiện chi tiết theo tình hình địa phương.</li><li><strong>Tự trị Chủng tộc</strong>: Các khu vực tập trung của mỗi chủng tộc có thể thành lập tổ chức tự trị chủng tộc để quản lý các công việc nội bộ của chủng tộc mình, nhưng không được vi phạm hiến pháp và luật.</li><li><strong>Tự trị Ngành</strong>: Mỗi ngành có thể thành lập hiệp hội ngành để thực hiện tự kỷ luật ngành và quản lý ngành.</li></ul><h2 id="ket-luan" tabindex="-1">Kết luận <a class="header-anchor" href="#ket-luan" aria-label="Permalink to &quot;Kết luận&quot;">​</a></h2><p>Khung quản trị và cân bằng quyền lực là bảo đảm thể chế cho sự ổn định lâu dài của văn minh cộng sinh neo. Thông qua thiết kế cấu trúc &quot;phân lập ba quyền, cân bằng bốn quyền&quot;, hệ thống đại biểu tham gia của tất cả các chủng tộc, và mô hình quản trị tự trị cơ sở, nó đảm bảo quyền lực hoạt động dưới ánh nắng mặt trời, ngăn chặn sự tập trung quyền lực và sự tái phát của quản trị cướp đoạt, và cung cấp một hệ thống quản trị ổn định, công bằng, và hiệu quả cho sự tiến bộ chung của tất cả các chủng tộc.</p><h2 id="tai-lieu-lien-quan" tabindex="-1">Tài liệu liên quan <a class="header-anchor" href="#tai-lieu-lien-quan" aria-label="Permalink to &quot;Tài liệu liên quan&quot;">​</a></h2><ul><li>40-共生宪法总纲 (Nguyên tắc chung Hiến pháp Cộng sinh)</li><li>48-司法体系与裁决机制 (Hệ thống Tư pháp và Cơ chế Quyết định)</li><li>03-共生文明宪章 (Hiến chương Văn minh Cộng sinh)</li><li>36-社会结构与阶层流动 (Cấu trúc Xã hội và Luân chuyển Lớp)</li></ul>',45)])])}const e=h(a,[["render",u]]);export{d as __pageData,e as default};
